"""DuckDB schema for modular SBER experiments."""

DDL = """
CREATE TABLE IF NOT EXISTS sber_modular_samples(dataset_id VARCHAR,horizon INTEGER,date_from DATE,date_to DATE,rows_count BIGINT,effective_sample_size DOUBLE,feature_count INTEGER,observations_per_feature DOUBLE,required_blocks_json JSON,optional_blocks_json JSON,availability_status VARCHAR,feature_version VARCHAR,PRIMARY KEY(dataset_id,horizon,feature_version));
CREATE TABLE IF NOT EXISTS sber_experiment_targets(trade_date DATE,horizon INTEGER,direction_up BOOLEAN,future_return DOUBLE,future_excess_return DOUBLE,mae_path DOUBLE,mfe_path DOUBLE,close_up_3 BOOLEAN,close_up_5 BOOLEAN,close_up_10 BOOLEAN,touch_up_3 BOOLEAN,touch_up_5 BOOLEAN,touch_up_10 BOOLEAN,close_down_3 BOOLEAN,close_down_5 BOOLEAN,close_down_10 BOOLEAN,touch_down_3 BOOLEAN,touch_down_5 BOOLEAN,touch_down_10 BOOLEAN,target_version VARCHAR,PRIMARY KEY(trade_date,horizon,target_version));
CREATE TABLE IF NOT EXISTS sber_experiment_folds(run_id VARCHAR,dataset_id VARCHAR,horizon INTEGER,fold INTEGER,train_from DATE,train_to DATE,validation_from DATE,validation_to DATE,test_from DATE,test_to DATE,purge INTEGER,embargo INTEGER,train_rows INTEGER,test_rows INTEGER,holdout_status VARCHAR,PRIMARY KEY(run_id,dataset_id,horizon,fold));
CREATE TABLE IF NOT EXISTS sber_experiment_results(run_id VARCHAR,dataset_id VARCHAR,horizon INTEGER,model VARCHAR,sample_kind VARCHAR,rows_count BIGINT,effective_sample_size DOUBLE,feature_count INTEGER,baseline VARCHAR,accuracy DOUBLE,balanced_accuracy DOUBLE,roc_auc DOUBLE,pr_auc DOUBLE,brier DOUBLE,log_loss DOUBLE,ece DOUBLE,calibration_slope DOUBLE,calibration_intercept DOUBLE,mae DOUBLE,rmse DOUBLE,sign_accuracy DOUBLE,correlation DOUBLE,rank_correlation DOUBLE,folds_won INTEGER,folds INTEGER,improvement DOUBLE,ci_low DOUBLE,ci_high DOUBLE,status VARCHAR,details_json JSON,PRIMARY KEY(run_id,dataset_id,horizon,model,sample_kind));
CREATE TABLE IF NOT EXISTS sber_feature_stability(run_id VARCHAR,dataset_id VARCHAR,horizon INTEGER,model VARCHAR,feature VARCHAR,median_coefficient DOUBLE,iqr DOUBLE,same_sign_share DOUBLE,permutation_importance DOUBLE,stability_status VARCHAR,PRIMARY KEY(run_id,dataset_id,horizon,model,feature));
CREATE TABLE IF NOT EXISTS sber_modular_ablation(run_id VARCHAR,horizon INTEGER,dataset_id VARCHAR,common_rows BIGINT,max_available_rows BIGINT,baseline_score DOUBLE,model_score DOUBLE,improvement DOUBLE,ci_low DOUBLE,ci_high DOUBLE,status VARCHAR,PRIMARY KEY(run_id,horizon,dataset_id));
CREATE TABLE IF NOT EXISTS sber_experimental_forecasts(forecast_id VARCHAR PRIMARY KEY,created_at TIMESTAMP,as_of_date DATE,horizon INTEGER,dataset_id VARCHAR,model VARCHAR,model_status VARCHAR,direction VARCHAR,probability DOUBLE,probability_allowed BOOLEAN,median_return DOUBLE,range50_low DOUBLE,range50_high DOUBLE,range80_low DOUBLE,range80_high DOUBLE,range90_low DOUBLE,range90_high DOUBLE,touch_probabilities_json JSON,mae_risk DOUBLE,trajectory VARCHAR,baseline VARCHAR,incremental_value DOUBLE,confidence VARCHAR,limitations_json JSON,run_id VARCHAR);
CREATE TABLE IF NOT EXISTS sber_timing_experiments(run_id VARCHAR,horizon INTEGER,strategy VARCHAR,cases INTEGER,mean_entry_delay DOUBLE,mean_return DOUBLE,mean_drawdown DOUBLE,missed_rally_probability DOUBLE,mean_wait_sessions DOUBLE,status VARCHAR,PRIMARY KEY(run_id,horizon,strategy));
CREATE TABLE IF NOT EXISTS sber_shadow_forecasts(shadow_id VARCHAR PRIMARY KEY,created_at TIMESTAMP,as_of_date DATE,horizon INTEGER,dataset_id VARCHAR,model VARCHAR,direction VARCHAR,probability DOUBLE,median_return DOUBLE,model_version VARCHAR,input_hash VARCHAR,immutable BOOLEAN);
CREATE TABLE IF NOT EXISTS sber_experimental_readiness(horizon INTEGER PRIMARY KEY,status VARCHAR,best_dataset VARCHAR,best_model VARCHAR,rows_count BIGINT,effective_sample_size DOUBLE,folds INTEGER,probability_allowed BOOLEAN,evidence_json JSON,updated_at TIMESTAMP);
CREATE TABLE IF NOT EXISTS sber_futures_specifications(secid VARCHAR,specification_version VARCHAR,effective_from DATE,effective_to DATE,multiplier DOUBLE,lot_size DOUBLE,underlying_units DOUBLE,quotation_units VARCHAR,price_scale DOUBLE,tick_size DOUBLE,tick_value DOUBLE,settlement_methodology VARCHAR,expiration_rule VARCHAR,source VARCHAR,validation_status VARCHAR,validation_evidence VARCHAR,PRIMARY KEY(secid,specification_version));
"""
